CREATE TABLE public.membership_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payer_id uuid NOT NULL REFERENCES public.profiles(id), user_id uuid NOT NULL REFERENCES public.profiles(id), amount integer NOT NULL CHECK(amount IN(80,100)), reference text NOT NULL UNIQUE, message_id uuid NOT NULL REFERENCES public.messages(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')), submitted_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, reviewed_by uuid, note text NOT NULL DEFAULT '');
GRANT SELECT ON public.membership_requests TO authenticated; GRANT ALL ON public.membership_requests TO service_role;
ALTER TABLE public.membership_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY membership_requests_read ON public.membership_requests TO authenticated USING(payer_id=auth.uid() OR user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.membership_access (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), request_id uuid UNIQUE REFERENCES public.membership_requests(id), source text NOT NULL CHECK(source IN('provisional','confirmed','admin')), starts_at timestamptz NOT NULL DEFAULT now(), ends_at timestamptz NOT NULL DEFAULT (now()+interval '1 month'), revoked_at timestamptz, granted_by uuid);
GRANT SELECT ON public.membership_access TO authenticated; GRANT ALL ON public.membership_access TO service_role;
ALTER TABLE public.membership_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY membership_access_read ON public.membership_access TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.has_paid_bell(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_allowed(_user) AND (EXISTS(SELECT 1 FROM public.prime99_payments WHERE user_id=_user AND payment_purpose='membership' AND payable_amount=100 AND status='approved' AND received_at<=now() AND ends_at>now()) OR EXISTS(SELECT 1 FROM public.membership_access WHERE user_id=_user AND revoked_at IS NULL AND starts_at<=now() AND ends_at>now())) $$;
CREATE OR REPLACE FUNCTION public.my_membership_price() RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM public.provider_contact_batches WHERE user_id=auth.uid() AND status='approved') THEN 80 ELSE 100 END $$;
CREATE OR REPLACE FUNCTION public.my_prime99() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('active',public.has_paid_bell(auth.uid()),'bell_active',public.has_paid_bell(auth.uid()),'alerts_ready',public.paid_alert_ready(auth.uid()),'ends_at',(SELECT max(ends_at) FROM (SELECT ends_at FROM public.prime99_payments WHERE user_id=auth.uid() AND payment_purpose='membership' AND status='approved' UNION ALL SELECT ends_at FROM public.membership_access WHERE user_id=auth.uid() AND revoked_at IS NULL) a),'provisional',EXISTS(SELECT 1 FROM public.membership_access WHERE user_id=auth.uid() AND source='provisional' AND revoked_at IS NULL AND ends_at>now()),'amount',100) $$;
CREATE FUNCTION public.register_membership_evidence(_payer uuid,_user uuid,_amount integer,_reference text,_message uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF NOT public.account_allowed(_payer) OR NOT public.account_allowed(_user) THEN RAISE EXCEPTION 'ACCOUNT_REQUIRED'; END IF; IF _reference !~ '^[0-9]{12}$' OR _amount NOT IN(80,100) THEN RAISE EXCEPTION 'INVALID_PAYMENT_EVIDENCE'; END IF; IF NOT EXISTS(SELECT 1 FROM public.messages m WHERE m.id=_message AND m.sender_id=_payer AND public.has_role(m.receiver_id,'admin') AND m.image_path LIKE _payer::text||'/%') THEN RAISE EXCEPTION 'IMAGE_REQUIRED'; END IF; IF _payer<>_user THEN IF _amount<>80 OR NOT EXISTS(SELECT 1 FROM public.referral_vip_joins WHERE joined_user=_user AND referrer_id=_payer) OR EXISTS(SELECT 1 FROM public.membership_requests WHERE user_id=_user AND payer_id<>user_id AND status<>'rejected') THEN RAISE EXCEPTION 'REFERRAL_REQUIRED'; END IF; ELSIF _amount=80 AND NOT EXISTS(SELECT 1 FROM public.provider_contact_batches WHERE user_id=_payer AND status='approved') THEN RAISE EXCEPTION 'CONTACT_APPROVAL_REQUIRED'; END IF; PERFORM 1 FROM public.profiles WHERE id=_user FOR UPDATE; SELECT id INTO rid FROM public.membership_requests WHERE reference=_reference; IF rid IS NOT NULL THEN IF EXISTS(SELECT 1 FROM public.membership_requests WHERE id=rid AND payer_id=_payer AND user_id=_user) THEN RETURN rid; END IF; RAISE EXCEPTION 'REFERENCE_ALREADY_USED'; END IF; IF EXISTS(SELECT 1 FROM public.prime99_payments WHERE reference=_reference) OR EXISTS(SELECT 1 FROM public.referral_cash_receipts WHERE reference=_reference) THEN RAISE EXCEPTION 'REFERENCE_ALREADY_USED'; END IF; IF EXISTS(SELECT 1 FROM public.membership_requests WHERE user_id=_user AND status='pending') THEN RAISE EXCEPTION 'REVIEW_PENDING'; END IF; INSERT INTO public.membership_requests(payer_id,user_id,amount,reference,message_id) VALUES(_payer,_user,_amount,_reference,_message) RETURNING id INTO rid; INSERT INTO public.membership_access(user_id,request_id,source) VALUES(_user,rid,'provisional'); INSERT INTO public.messages(sender_id,receiver_id,body,is_auto) VALUES(public.support_admin_id(),_user,'మీ స్క్రీన్ షాట్ అందింది! మీకు తాత్కాలిక ప్రైమ్ మెంబర్ షిప్ ఆన్ అయింది. మేము చెల్లింపు పరిశీలిస్తాం. ధన్యవాదాలు!',true); INSERT INTO public.messages(sender_id,receiver_id,body,needs_admin,is_auto) VALUES(_payer,public.support_admin_id(),'కొత్త యూజర్ తాత్కాలిక ప్రైమ్ ఆన్ అయింది - UTR నంబర్, స్క్రీన్ షాట్ చూడండి',true,true); RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.register_membership_evidence(uuid,uuid,integer,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.register_membership_evidence(uuid,uuid,integer,text,uuid) TO service_role;
CREATE FUNCTION public.review_membership_evidence(_id uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.membership_requests; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; SELECT * INTO r FROM public.membership_requests WHERE id=_id FOR UPDATE; IF r.id IS NULL OR r.status<>'pending' THEN RAISE EXCEPTION 'REVIEW_REQUIRED'; END IF; UPDATE public.membership_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,reviewed_at=now(),reviewed_by=auth.uid() WHERE id=_id; UPDATE public.membership_access SET source=CASE WHEN _approve THEN 'confirmed' ELSE source END,starts_at=CASE WHEN _approve THEN now() ELSE starts_at END,ends_at=CASE WHEN _approve THEN now()+interval '1 month' ELSE ends_at END,revoked_at=CASE WHEN _approve THEN NULL ELSE now() END,granted_by=auth.uid() WHERE request_id=_id; IF _approve AND r.payer_id=r.user_id THEN PERFORM public.confirm_referral_cash(r.user_id,r.reference,r.amount::bigint*100); END IF; INSERT INTO public.messages(sender_id,receiver_id,body,is_auto) VALUES(auth.uid(),r.user_id,CASE WHEN _approve THEN 'మీ చెల్లింపు పరిశీలించాం. మీ ప్రైమ్ మెంబర్ షిప్ ఒక నెల వరకు ఉంటుంది. ధన్యవాదాలు!' ELSE 'మీ చెల్లింపు నిర్ధారణ కాలేదు. తాత్కాలిక ప్రైమ్ ఆఫ్ చేశాం. అడ్మిన్ తో చాట్ చేయండి.' END,true); END $$;
REVOKE ALL ON FUNCTION public.review_membership_evidence(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_membership_evidence(uuid,boolean) TO authenticated,service_role;
CREATE FUNCTION public.admin_membership_access(_user uuid,_enable boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; PERFORM 1 FROM public.profiles WHERE id=_user FOR UPDATE; IF _enable THEN INSERT INTO public.membership_access(user_id,source,granted_by) VALUES(_user,'admin',auth.uid()); ELSE UPDATE public.membership_access SET revoked_at=now() WHERE user_id=_user AND revoked_at IS NULL; UPDATE public.prime99_payments SET ends_at=least(ends_at,now()),review_note=review_note||' | Admin access revoked' WHERE user_id=_user AND payment_purpose='membership' AND status='approved' AND ends_at>now(); END IF; END $$;
REVOKE ALL ON FUNCTION public.admin_membership_access(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_membership_access(uuid,boolean) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.consume_post_slot(_user uuid,_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE anchor public.monthly_post_periods; used integer; credit uuid; BEGIN PERFORM 1 FROM public.profiles WHERE id=_user FOR UPDATE; SELECT * INTO anchor FROM public.monthly_post_periods WHERE user_id=_user; IF anchor.user_id IS NULL OR anchor.ends_at<=now() THEN INSERT INTO public.monthly_post_periods(user_id,starts_at,ends_at) VALUES(_user,now(),now()+interval '1 month') ON CONFLICT(user_id) DO UPDATE SET starts_at=excluded.starts_at,ends_at=excluded.ends_at RETURNING * INTO anchor; END IF; SELECT count(*) INTO used FROM public.monthly_post_usage WHERE user_id=_user AND used_at>=anchor.starts_at AND used_at<anchor.ends_at; IF used>=3 AND NOT public.has_paid_bell(_user) THEN SELECT id INTO credit FROM public.prime99_payments WHERE user_id=_user AND payment_purpose='extra_post' AND payable_amount=49 AND status='approved' AND used_post_id IS NULL ORDER BY received_at,id LIMIT 1 FOR UPDATE; IF credit IS NULL THEN RAISE EXCEPTION 'MONTHLY_THREE_POST_LIMIT'; END IF; UPDATE public.prime99_payments SET used_post_id=_id WHERE id=credit; END IF; INSERT INTO public.monthly_post_usage(post_id,user_id) VALUES(_id,_user); END $$;
ALTER TABLE public.vehicle_route_preferences ADD COLUMN vehicle_type text NOT NULL DEFAULT ''; ALTER TABLE public.vehicle_route_preferences ADD COLUMN capacity_tons integer;
CREATE FUNCTION public.save_detailed_vehicle_route(_from text,_to text,_vehicle text,_tons integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF length(trim(_from)) NOT BETWEEN 1 AND 120 OR length(trim(_to)) NOT BETWEEN 1 AND 120 OR lower(trim(_from))=lower(trim(_to)) OR _vehicle NOT IN('Mini Truck','Truck','Lorry','Pickup','Auto','Tata Ace') OR _tons NOT IN(1,2,3,5,10,15) THEN RAISE EXCEPTION 'ROUTE_DETAILS_REQUIRED'; END IF; PERFORM 1 FROM public.profiles WHERE id=auth.uid() FOR UPDATE; SELECT id INTO rid FROM public.vehicle_route_preferences WHERE user_id=auth.uid() AND lower(trim(from_place))=lower(trim(_from)) AND lower(trim(to_place))=lower(trim(_to)); IF rid IS NULL THEN INSERT INTO public.vehicle_route_preferences(user_id,from_place,to_place,vehicle_type,capacity_tons) VALUES(auth.uid(),trim(_from),trim(_to),_vehicle,_tons) RETURNING id INTO rid; ELSE UPDATE public.vehicle_route_preferences SET vehicle_type=_vehicle,capacity_tons=_tons,enabled=true WHERE id=rid AND user_id=auth.uid(); END IF; RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.save_detailed_vehicle_route(text,text,text,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_detailed_vehicle_route(text,text,text,integer) TO authenticated,service_role;
COMMENT ON TABLE public.membership_access IS 'Provisional and admin access are not verified receipts or cash rewards; one-month cap, revocable, owner/admin read only.';